button.clickEventHandler:
var facility = data.requisites.find(re => re.name == "Facility").value;
if (facility != null) {
  ESS.actions.facilityActions.runFacility({id: facility}, {parameters:{AssignmentId: data.id, AssignmentType: data.name}});
  ESS.closeElement(sender);
}

objectCard.openedEventHandler:
    var assignmentId = data.id;
    var remark = data.requisites.find(re => re.name == "Remark").value;
    if (remark) {
      data.remark = remark.replace(/([\r\n])/g, '<br/>');
    }
	
    var isSubstitutionAllowed = data.requisites.find(re => re.name == "IsSubstitutionAllowed").value ?? true;
    ESS.network.sendRequest(`/api/functions/CheckIfCurrentUserIsPerformer?personId=$(CurrentUser.DirectumRX.PersonId)&assignmentId=${data.id}`)
    .then(function (isPerformer){
      if (!isPerformer){
        if (!isSubstitutionAllowed){
          data.isSubstitutionNotAllowedMessage = ESS.L('@HRPROSTATEMENTS.SUBSTITUTION_NOT_ALLOWED');
          data.isSubstitutionAllowed = isSubstitutionAllowed;
          functions.setVisibility(['Rework', 'Abort'], ESS.enums.Visibility.HIDDEN);
        }
      }
    })
	
    ESS.network.sendRequest(`/api/functions/GetAssignmentInstructionForEss?assignmentId=${assignmentId}`)
    .then(function (instruction) {
      if (instruction && data.status != 'Completed') {
        configuration.content = ESS.L('@HRPROVACATIONS.COMMON_INSTRUCTION') + '<br/><br/>' + instruction;
      }      
      resolve({configuration: configuration, data: data});
    })
    .catch(function (error) {
      ESS.toasts.showToast(error.message, 'danger', false);
      reject();
    });
